const STORAGE='kargo.routes.v1';
const Bursa=[
  {address:'Dobruca Mahallesi, 2. Sokak No: 12, Osmangazi/Bursa',lat:40.2018,lng:29.0118,recipient:'Ayşe Demir',company:'Dobruca Eczanesi',phone:'05321234567',parcel:'KR-1042',count:1,notes:'Girişte güvenliğe bırakmayın',priority:'high'},
  {address:'Çekirge Mahallesi, 1. Murat Caddesi No: 8, Osmangazi/Bursa',lat:40.1983,lng:29.0415,recipient:'Mehmet Yılmaz',company:'Çekirge Ofis',phone:'05329876543',parcel:'KR-1043',count:2,notes:'',priority:'normal'},
  {address:'Altıparmak Mahallesi, Çarşamba Caddesi No: 25, Osmangazi/Bursa',lat:40.1939,lng:29.0547,recipient:'Selin Kaya',company:'Altıparmak Kırtasiye',phone:'05325553322',parcel:'KR-1044',count:1,notes:'Öğleden sonra teslimat',priority:'normal'},
  {address:'Setbaşı Mahallesi, Atatürk Caddesi No: 54, Osmangazi/Bursa',lat:40.1799,lng:29.0709,recipient:'Ali Çelik',company:'Setbaşı Market',phone:'05321112233',parcel:'KR-1045',count:3,notes:'',priority:'normal'}
];
const sampleCompanies=Bursa.map(x=>({name:x.company,...x}));
const initial=()=>({routes:[],activeId:null,screen:'home',selectedId:null,view:'list',navigation:null,config:{mode:'demo'},addressBook:[],searchGoogle:false,bookQuery:'',draft:{title:'',start:{address:'Bursa merkez',lat:40.195,lng:29.06},end:null,stops:[]},edit:null,searchResults:[],searchPending:false,quickQuery:'',quickResults:[],quickPending:false,quickError:'',error:'',notice:'',busy:false,mapSelect:false});
const state=initial();
try {const saved=JSON.parse(localStorage.getItem(STORAGE)||'{}');state.routes=Array.isArray(saved.routes)?saved.routes:[];state.activeId=saved.activeId||null;state.addressBook=Array.isArray(saved.addressBook)?saved.addressBook:[];}catch{}
const app=document.querySelector('#app');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID?.()||String(Date.now()+Math.random());
const snapshot=()=>({routes:state.routes,activeId:state.activeId,addressBook:state.addressBook});
let syncRevision=0,syncTimer,syncBusy=false,syncPending=false,syncReady=false,syncMessage='',syncDirty=false,syncVersion=0,user=null,authError='',authLoading=true,setupView=false;
let localOwner=localStorage.getItem('kargo.local.owner');
const legacyToken=localStorage.getItem('kargo.sync.token')||'';
const PENDING='kargo.sync.pending.v1',CLOUD_REVISION='kargo.sync.revision.v1',BACKUPS='kargo.backups.v1';
function backupLocal(data,reason){
  if(!data?.routes?.length&&!data?.addressBook?.length)return;
  try{
    const history=JSON.parse(localStorage.getItem(BACKUPS)||'[]');
    if(JSON.stringify(history.at(-1)?.data)===JSON.stringify(data))return;
    history.push({at:new Date().toISOString(),reason,owner:localOwner||user?.id||null,data});
    for(let count=Math.min(history.length,5);count>0;count--){
      try{localStorage.setItem(BACKUPS,JSON.stringify(history.slice(-count)));return}catch{}
    }
  }catch{}
}
const persist=()=>{if(!user)return;localStorage.setItem(STORAGE,JSON.stringify(snapshot()));localStorage.setItem(PENDING,user.id);syncDirty=true;syncVersion++;if(syncReady){clearTimeout(syncTimer);syncTimer=setTimeout(saveCloud,650)}};
async function syncRequest(method,data){return api('sync',{method,headers:data?{'Content-Type':'application/json'}:{},...(data?{body:JSON.stringify(data)}:{})})}
async function saveCloud(){if(!syncReady||!user||!syncDirty)return;if(syncBusy){syncPending=true;return}syncBusy=true;const version=syncVersion,body={data:snapshot(),revision:syncRevision};try{const result=await syncRequest('PUT',body);syncRevision=result.revision;localStorage.setItem(CLOUD_REVISION,String(syncRevision));syncDirty=syncVersion!==version;if(!syncDirty)localStorage.removeItem(PENDING);syncMessage=syncDirty?'Yeni değişiklikler eşitleniyor…':'Eşitlendi'}catch(err){syncMessage=err.status===409?'Başka cihazda değişiklik var. Bu cihazdaki kayıtları koruduk; Ayarlar’dan verileri yenile.':err.status===401?'Oturum kapandı. Yeniden giriş yap.':'Bağlantı kesildi; kayıt bu cihazda bekliyor.';if(err.status===401){user=null;syncReady=false}}finally{syncBusy=false;if(syncPending||syncDirty&&syncVersion!==version){syncPending=false;clearTimeout(syncTimer);syncTimer=setTimeout(saveCloud,900)}if(state.screen==='settings'||!user)render()}}
async function loadCloud(merge=false){if(!user)return;syncMessage='Kayıtlar yükleniyor…';try{const result=await syncRequest('GET');syncRevision=result.revision;let incoming=result.data;
  let legacyRecovered=false;
  if(merge&&legacyToken&&!localOwner){try{const old=await api('sync',{headers:{Authorization:'Bearer '+legacyToken}});if(old.data){legacyRecovered=hasLocalOnly(incoming,old.data);incoming=mergeSnapshots(incoming,old.data)}}catch{syncMessage='Eski kayıtlar okunamadı. Bu tarayıcıdaki kayıtlar deneniyor.'}}
  const local=snapshot(),sameOwner=!localOwner||localOwner===user.id;
  const knownRevision=Number(localStorage.getItem(CLOUD_REVISION));
  const pendingLocal=localStorage.getItem(PENDING)===user.id||syncDirty;
  const recoverLocal=sameOwner&&(pendingLocal||hasLocalOnly(incoming,local)&&(!localStorage.getItem(CLOUD_REVISION)||knownRevision>result.revision));
  backupLocal(local,'Bulut kayıtları yüklenmeden önce');
  if(recoverLocal)incoming=mergeSnapshots(incoming,local,{preferLocal:pendingLocal});
  state.routes=incoming?.routes||[];state.addressBook=incoming?.addressBook||[];state.activeId=incoming?.activeId||null;
  localOwner=user.id;localStorage.setItem('kargo.local.owner',user.id);localStorage.setItem(STORAGE,JSON.stringify(snapshot()));
  localStorage.setItem(CLOUD_REVISION,String(syncRevision));syncReady=true;
  syncDirty=Boolean(recoverLocal||legacyRecovered);
  if(syncDirty){localStorage.setItem(PENDING,user.id);syncVersion++;syncMessage='Eski kayıtlar bulundu; buluta eşitleniyor…';await saveCloud()}
  else{localStorage.removeItem(PENDING);syncMessage='Eşitlendi'}
  render();
}catch(err){syncMessage='Veritabanına ulaşılamadı. Daha sonra tekrar dene.';syncReady=false;render()}}
function authScreen(){const setup=setupView&&state.config.ownerSetupAvailable;return `<div class="auth-shell"><div class="auth-art"><span class="auth-mark">K</span><span class="auth-label">KARGO · ROTA ASİSTANI</span><h1>Dağıtımın<br><em>kontrolü sende.</em></h1><p>İşletmeleri hızlıca ekle. Rotaların tüm cihazlarında hazır olsun.</p><div class="auth-path"><span>⌖</span><i></i><span>↗</span><i></i><span>✓</span></div></div><div class="auth-card"><h2>${setup?'İlk hesabını kur':'Tekrar hoş geldin'}</h2><p class="muted">${setup?'Bu kurulum tek kullanımlıktır. Hesap oluşturulunca yeni kayıtlar kapanır.':'Aynı hesapla giriş yaptığında rotaların ve adres depon otomatik yüklenir.'}</p><form id="auth-form" class="auth-form"><label class="field">E-posta<input name="email" type="email" inputmode="email" autocomplete="email" required placeholder="ornek@firma.com"></label><label class="field">Şifre<input name="password" type="password" minlength="12" autocomplete="${setup?'new-password':'current-password'}" required placeholder="En az 12 karakter"></label>${setup?`<label class="field">Şifreyi tekrar yaz<input name="confirmPassword" type="password" minlength="12" autocomplete="new-password" required placeholder="Şifreni doğrula"></label><label class="field">Tek kullanımlık kurulum anahtarı<input name="setupSecret" type="password" autocomplete="off" required placeholder="Vercel'deki kurulum anahtarı"></label>`:''}${authError?`<p class="notice error" role="alert">${esc(authError)}</p>`:''}<button type="submit" class="primary">${setup?'İlk hesabımı oluştur ↗':'Giriş yap ↗'}</button></form>${state.config.ownerSetupAvailable?`<button class="auth-switch" data-action="auth-setup">${setup?'← Giriş yap':'İlk hesabımı kur →'}</button>`:''}<p class="auth-foot">${setup?'Kurulum anahtarını yalnızca sen bilmelisin. Normal girişte tekrar gerekmez.':'Kendi hesabınla farklı cihazlardan aynı kayıtları aç.'}</p></div></div>`}

async function startSession(){try{const result=await api('session');user=result.user;if(user){if(localOwner&&localOwner!==user.id){backupLocal(snapshot(),'Farklı hesapla giriş öncesi');state.routes=[];state.addressBook=[];state.activeId=null}await loadCloud(true)}}catch{authError='Bağlantı kurulamadı. Sayfayı yenileyip tekrar dene.'}finally{authLoading=false;render()}}

const route=()=>state.routes.find(r=>r.id===state.activeId);
const pending=r=>r.stops.filter(s=>s.status==='pending');
const norm=s=>String(s||'').toLocaleLowerCase('tr-TR').trim();
const googleFresh=x=>x.origin!=='google'||Date.now()-new Date(x.savedAt||0).getTime()<29*86400000;
function rememberStop(stop){if(!stop?.address||stop.lat==null||stop.lng==null)return;const prior=state.addressBook.find(x=>stop.placeId&&x.placeId===stop.placeId||norm(x.address)===norm(stop.address));const entry={id:prior?.id||id(),company:stop.company||prior?.company||'',address:stop.address,lat:stop.lat,lng:stop.lng,placeId:stop.placeId||null,recipient:stop.recipient||prior?.recipient||'',phone:stop.phone||prior?.phone||'',notes:stop.notes||prior?.notes||'',origin:stop.origin||prior?.origin||(stop.placeId?'google':'manual'),savedAt:stop.savedAt||new Date().toISOString()};if(prior)Object.assign(prior,entry);else state.addressBook.unshift(entry);persist()}

async function freshBookLocation(entry){if(googleFresh(entry))return entry;if(state.config.mode!=='live')throw new Error('Bu adresin konumu yenilenmeli. Google bağlantısını kontrol et.');const result=entry.placeId?await api('place?id='+encodeURIComponent(entry.placeId)):await verifyAddress(entry.address);Object.assign(entry,{lat:result.lat,lng:result.lng,placeId:result.placeId||entry.placeId,savedAt:new Date().toISOString(),origin:'google'});persist();return entry}
async function addBookStop(entry){try{state.busy=true;const location=await freshBookLocation(entry);const r=ensureQuickRoute();const item={...emptyEdit(),...location,id:id(),status:'pending',reason:''};r.stops.push(item);state.selectedId=item.id;invalidate(r);state.quickQuery='';state.quickResults=[];state.searchGoogle=false;persist();render();toast(`${item.company||item.address} rotaya eklendi`)}catch(err){state.quickError=err.message;render()}finally{state.busy=false}}

