const date=s=>new Date(s).toLocaleDateString('tr-TR',{day:'numeric',month:'long',year:'numeric'});
const time=s=>new Date(s).toLocaleTimeString('tr-TR',{hour:'2-digit',minute:'2-digit'});
const formatDuration=s=>{const minutes=Math.ceil(s/60);return minutes>=60?`${Math.floor(minutes/60)} sa ${minutes%60} dk`:`${minutes} dk`};
