  const saved=state.addressBook.filter(c=>norm(`${c.company} ${c.address} ${c.recipient}`).includes(norm(query))).slice(0,8).map(c=>({...c,bookId:c.id,name:c.company,label:c.address}));
  const examples=state.config.mode==='demo'?sampleCompanies.filter(c=>norm(`${c.name} ${c.address}`).includes(norm(query))).map(c=>({...c,label:c.address})):[];
  state.quickResults=query.length>=2?[...saved,...examples]:[];
  state.quickPending=false;
  updateQuick();
  if(query.length<3)return;
  if(saved.length&&!forceGoogle)return;
  if(state.config.mode==='demo'){if(!state.quickResults.length)state.quickError='Demo modunda yalnızca örnek Bursa işletmeleri bulunur.';updateQuick();return}
  state.quickPending=true;updateQuick();
